--questions
select * from customer limit 1
--1) what is revenue generated by male and female customers

SELECT
	GENDER,
	SUM(PURCHASE_AMOUNT)
FROM
	CUSTOMER
GROUP BY
	GENDER;

--2) which customer used discount but still spent more money than average purchase amount?

SELECT
	CUSTOMER_ID,
	PURCHASE_AMOUNT
FROM
	CUSTOMER
WHERE
	DISCOUNT_APPLIED = 'Yes'
	AND PURCHASE_AMOUNT >= (
		SELECT
			AVG(PURCHASE_AMOUNT)
		FROM
			CUSTOMER
	);

--3) Which are the top 5 products with the highest average review rating?
SELECT
	ITEM_PURCHASED,
	round(AVG(REVIEW_RATING:: numeric),2)
FROM
	CUSTOMER
GROUP BY
	ITEM_PURCHASED
ORDER BY
	AVG(REVIEW_RATING) DESC LIMiT 5;


--Q4. Compare the average Purchase Amounts between Standard and Express Shipping.

SELECT
	SHIPPING_TYPE,
	AVG(PURCHASE_AMOUNT) AS AVG_PURCHASE_AMT
FROM
	CUSTOMER where shipping_type in ('Express','Standard')
GROUP BY
	SHIPPING_TYPE;

--Q5. Do subscribed customers spend more? Compare average spend and total revenue 

select subscription_status, round(avg(purchase_amount:: numeric),2), sum(purchase_amount) from customer group by 1;

-- NO, SUBSCRIBED CUSTOMERS DO NOT SPEND MORE

--Q6. Which 5 products have the highest percentage of purchases with discounts applied?

SELECT
	ITEM_PURCHASED,
	round(100*sum(case when discount_applied = 'Yes' then 1 else 0 end)/count(*),2) as discount_rate
FROM
	CUSTOMER
WHERE
	DISCOUNT_APPLIED = 'Yes'
GROUP BY
	ITEM_PURCHASED
ORDER BY
	discount_rate DESC
LIMIT
	5;


--Q7. Segment customers into New, Returning, and Loyal based on their total 
-- number of previous purchases, and show the count of each segment. 

SELECT
	CASE
		WHEN PREVIOUS_PURCHASES = 1 THEN 'New'
		WHEN PREVIOUS_PURCHASES <= 10 THEN 'returning'
		ELSE 'loyal'
	END AS CUSTOMER_SEGMENT,
	COUNT(*)
FROM
	CUSTOMER
GROUP BY
	CUSTOMER_SEGMENT;


--Q8. What are the top 3 most purchased products within each category? 

with category_count as(
select item_purchased,category,count(customer_id) as item_count, row_number() over(partition by category order by count(customer_id) desc) as rn
from customer
group by category,item_purchased
)

select rn,item_purchased,category from category_count where rn<=3;



